package com.loopers.infrastructure.queue;import com.loopers.config.redis.RedisConfig;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.core.io.ClassPathResource;import org.springframework.data.redis.core.*;import org.springframework.data.redis.core.script.DefaultRedisScript;import org.springframework.stereotype.Component;import java.util.*;
// Hides: Lua atomicity, Redis key layout, and terminal slot release.
@Component public class RedisAdmissionStore{private final RedisTemplate<String,String> redis;private static final String KEY="w8:admission:pending";private static final DefaultRedisScript<Long>SCRIPT=script();public RedisAdmissionStore(@Qualifier(RedisConfig.REDIS_TEMPLATE_MASTER)RedisTemplate<String,String> redis){this.redis=redis;}private static DefaultRedisScript<Long> script(){DefaultRedisScript<Long>s=new DefaultRedisScript<>();s.setLocation(new ClassPathResource("redis/admission.lua"));s.setResultType(Long.class);return s;}public boolean admit(String id,int capacity){return Objects.equals(redis.execute(SCRIPT,List.of(KEY),id,String.valueOf(capacity)),1L);}public void terminal(String id){redis.opsForHash().delete(KEY,id);}public long pending(){return redis.opsForHash().size(KEY);}public void clear(){redis.delete(KEY);}}
